KG42.register("edges-696c2627493344f2d1c493e7",{"id":"S-ded5b6cd15f39921","source":"COMP-ab3d11c48c98c7be","type":"links","target":"KG31-c53b1d455f59fded","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["08-real_time_prices"],"assertions":[{"id":"08-real_time_prices::v141-c-R006::E::v141-c-R006-E001","paper":"08-real_time_prices","rule_id":"v141-c-R006","rule_ref":"08-real_time_prices::v141-c-R006","record":{"edge_id":"v141-c-R006-E001","source":"coordination.price_signal","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R006-C001"],"evidence_ids":["v141-b-g01-ev01","v141-b-g01-ev09"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R006-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-ab3d11c48c98c7be","target":"KG31-c53b1d455f59fded","source_occurrence_id":"08-real_time_prices::v141-c-R006::V::coordination.price_signal","target_occurrence_id":"08-real_time_prices::v141-c-R006::V::participation.prosumer","source_unit_id":"08-real_time_prices::v141-a-M01::coordination.price_signal","target_unit_id":"08-real_time_prices::v141-a-M01::participation.prosumer","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Bidless participation by small-scale DERs in EcoGrid EU. | Participating supply-capable prosumers and the TSO's expected balancing response in EcoGrid EU. | Proposed anti-arbitrage participation rules for the EcoGrid EU real-time market. | Small-scale DER participation in the EcoGrid EU bidless real-time market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev01","v141-b-g01-ev09","v141-b-g01-ev18","v141-b-g01-ev30","v141-b-g02-ev-16","v141-b-g03-e07"]},"active":true,"source_signature":"be55b9d334348825c5729c3c9c7fde1ed47ba84700c84321fc2b8782521c8ba2","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"TSO sets and publishes the next five-minute response price using operating status and single-period or scenario-based welfare optimization; absence of imbalance/congestion gives the day-ahead price. Keep planning-only next-day signals, forecasts and metering alignment as distinct contextual branches.","target_definition":"Supply-capable participant role and conditions in this mechanism: TSO stochastic balancing optimization posts five-minute prices; small consumers/DERs respond without bids or schedules and without obligations to deliver assumed response.","constraints":[{"constraint_id":"v141-c-R006-C001","kind":"procedural","role":"core","statement":"Real-time price-signal coordination enables small-scale DERs to participate by receiving and responding to 5-minute electricity prices. Scope: Small-scale DER participation in the EcoGrid EU bidless real-time market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev01","v141-b-g01-ev09"]}],"evidence":[{"evidence_id":"v141-b-g01-ev01","location":{"location_id":"src-da8e4e26d6-p01-c1r2__v141-a-M01-participation","page":1,"printed_page":null,"section":"Abstract","anchor_text":"g g y g penetration of renewable generation. Additionally, the develop- ment in communication techno","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"In this project, small-scale DERs and small end-consumers can actively participate in a new real-time electricity market by responding to 5-min real time electricity prices. In this way, the market operator will also obtain additional balancing power to cancel out the production variation introduced by renewable electricity generation."},{"evidence_id":"v141-b-g01-ev09","location":{"location_id":"src-da8e4e26d6-p02-c2r3__v141-a-M01-participation","page":2,"printed_page":null,"section":"I. INTRODUCTION","anchor_text":"on and respond to real-time prices for providing balancing ser- ght vices. The bidless real time mar","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"It will include a new bidless real time market concept designed to incorporate end-consumers as well as small-scale DERs into the market structure by letting them receive and respond to real-time prices for providing balancing services. The bidless real time market will remove the barriers that end-consumers as well as small-scale DERs have previously been facing to enter the present market structure, e.g., requirements on size, and a significant administrative burden including bidding in the markets, complying with schedules, etc. The market tool will provide a transparent and simple mechanism to encourage the participation of small end-consumers and small-scale DERs."}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Bidless participation by small-scale DERs in EcoGrid EU. | Participating supply-capable prosumers and the TSO's expected balancing response in EcoGrid EU. | Proposed anti-arbitrage participation rules for the EcoGrid EU real-time market. | Small-scale DER participation in the EcoGrid EU bidless real-time market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev01","v141-b-g01-ev09","v141-b-g01-ev18","v141-b-g01-ev30","v141-b-g02-ev-16","v141-b-g03-e07"]},"source_record":{"edge_id":"v141-c-R006-E001","source":"coordination.price_signal","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R006-C001"],"evidence_ids":["v141-b-g01-ev01","v141-b-g01-ev09"]},"paper_scope_note":"Single-period and multi-period optimization are kept separate; RP bidders and quote-free responders are kept separate; temporal precedence is not treated as mechanism necessity."}}],"assertion_ids":["08-real_time_prices::v141-c-R006::E::v141-c-R006-E001"]});
